package com.notepocket.app;

import android.content.*;
import android.database.sqlite.SQLiteDatabase;
import android.graphics.*;
import android.text.*;
import androidx.exifinterface.media.ExifInterface;
import java.io.*;
import java.util.*;
import java.util.regex.*;

/** Stable references to stored documents; pixels never enter note text, Binder or sync metadata. */
final class InlineImages {
    static final int MAX_IMAGES=100;static final long MAX_BYTES=32L*1024*1024;
    private static final Pattern IMAGE=Pattern.compile("(?m)^ {0,3}!\\[[^\\]\\r\\n]{0,120}\\]\\(notepocket-image:([A-Za-z0-9-]{1,80})\\)[ \\t]*\\r?$");
    private static final Pattern FENCE=Pattern.compile("(?m)^ {0,3}(`{3,}|~{3,})([^\\r\\n]*)\\r?$");
    static final class Block {final int start,end,idStart,idEnd;final String id;Block(Matcher m){start=m.start();end=m.end();idStart=m.start(1);idEnd=m.end(1);id=m.group(1);}}
    static List<Block> find(String text){List<Block> result=new ArrayList<>();if(!text.contains("](notepocket-image:"))return result;List<int[]> code=new ArrayList<>();Matcher fence=FENCE.matcher(text);int from=0;while(fence.find(from)){String ticks=fence.group(1);Matcher close=Pattern.compile("(?m)^ {0,3}"+Pattern.quote(ticks.substring(0,1))+"{"+ticks.length()+",}[ \\t]*\\r?$").matcher(text);if(close.find(fence.end())){code.add(new int[]{fence.start(),close.end()});from=close.end();}else{code.add(new int[]{fence.start(),text.length()});break;}}for(DiagramSource.Block b:DiagramSource.find(text))code.add(new int[]{b.start,b.end});Matcher image=IMAGE.matcher(text);while(image.find()){boolean inCode=false;for(int[] r:code)if(image.start()>=r[0]&&image.start()<r[1]){inCode=true;break;}if(!inCode)result.add(new Block(image));}return result;}
    static Set<String> ids(String text){Set<String> ids=new LinkedHashSet<>();for(Block b:find(text))ids.add(b.id);return ids;}
    static String marker(String id){valid(id);return "![รูปภาพ](notepocket-image:"+id+")";}
    static File file(Context context,String id){valid(id);return new File(context.getFilesDir(),id);}
    private static void valid(String id){if(id==null||!id.matches("[A-Za-z0-9-]{1,80}"))throw new IllegalArgumentException("Invalid image reference");}
    static boolean isImage(String name,String mime){if(mime!=null&&mime.startsWith("image/"))return true;return name!=null&&name.toLowerCase(Locale.ROOT).matches(".*\\.(jpg|jpeg|png|webp|gif|bmp|heic|heif|avif)$");}
    static Bitmap decode(File file,int width,long pixels) throws IOException {BitmapFactory.Options o=new BitmapFactory.Options();o.inJustDecodeBounds=true;BitmapFactory.decodeFile(file.getPath(),o);if(o.outWidth<1||o.outHeight<1||(long)o.outWidth*o.outHeight>200000000L)throw new IOException("Unsupported image");o.inJustDecodeBounds=false;o.inSampleSize=1;while(o.outWidth/o.inSampleSize>Math.max(320,width)*2||(long)(o.outWidth/o.inSampleSize)*(o.outHeight/o.inSampleSize)>pixels)o.inSampleSize*=2;o.inPreferredConfig=Bitmap.Config.ARGB_8888;Bitmap bitmap=BitmapFactory.decodeFile(file.getPath(),o);if(bitmap==null)throw new IOException("Cannot decode image");int orientation=ExifInterface.ORIENTATION_NORMAL;try{orientation=new ExifInterface(file).getAttributeInt(ExifInterface.TAG_ORIENTATION,ExifInterface.ORIENTATION_NORMAL);}catch(IOException ignored){}Matrix matrix=new Matrix();switch(orientation){case ExifInterface.ORIENTATION_FLIP_HORIZONTAL:matrix.setScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_180:matrix.setRotate(180);break;case ExifInterface.ORIENTATION_FLIP_VERTICAL:matrix.setScale(1,-1);break;case ExifInterface.ORIENTATION_TRANSPOSE:matrix.setRotate(90);matrix.postScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_90:matrix.setRotate(90);break;case ExifInterface.ORIENTATION_TRANSVERSE:matrix.setRotate(270);matrix.postScale(-1,1);break;case ExifInterface.ORIENTATION_ROTATE_270:matrix.setRotate(270);break;}if(!matrix.isIdentity()){try{Bitmap rotated=Bitmap.createBitmap(bitmap,0,0,bitmap.getWidth(),bitmap.getHeight(),matrix,true);if(rotated!=bitmap)bitmap.recycle();bitmap=rotated;}catch(OutOfMemoryError e){bitmap.recycle();throw e;}}return bitmap;}
    static ContentValues importImage(Context context,Store store,InputStream input,String name) throws Exception {String id=UUID.randomUUID().toString();File stage=new File(context.getCacheDir(),"photo-"+id+".tmp"),destination=file(context,id);boolean done=false,created=false;try{try(OutputStream out=new FileOutputStream(stage)){Backup.copy(input,out,MAX_BYTES);}BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(stage.getPath(),bounds);if(bounds.outWidth<1||bounds.outHeight<1||(long)bounds.outWidth*bounds.outHeight>200000000L)throw new IOException("Unsupported image");Bitmap check=decode(stage,320,300000);check.recycle();if(!destination.createNewFile())throw new IOException("Image already exists");created=true;try(InputStream in=new FileInputStream(stage);OutputStream out=new FileOutputStream(destination)){Backup.copy(in,out,MAX_BYTES);}ContentValues doc=new ContentValues();doc.put("id",id);doc.put("name",name==null||name.trim().isEmpty()?"รูปภาพ":name);doc.put("mime",bounds.outMimeType==null?"image/jpeg":bounds.outMimeType);doc.put("size",destination.length());store.getWritableDatabase().insertOrThrow("docs",null,doc);done=true;return doc;}finally{stage.delete();if(created&&!done)destination.delete();}}
    static final class Mapped {final String body,rich;Mapped(String body,String rich){this.body=body;this.rich=rich;}}
    static Mapped remap(String body,String rich,Map<String,String> ids){List<Block> blocks=find(body);if(blocks.isEmpty())return new Mapped(body,rich);SpannableStringBuilder text=NoteFormat.decode(rich,body);for(int i=blocks.size()-1;i>=0;i--){Block b=blocks.get(i);String replacement=ids.get(b.id);if(replacement!=null){valid(replacement);text.replace(b.idStart,b.idEnd,replacement);}}return new Mapped(text.toString(),rich==null||rich.isEmpty()?"":NoteFormat.encode(text));}
    static Mapped remove(String body,String rich,String id){List<Block> blocks=find(body);if(blocks.isEmpty())return new Mapped(body,rich);SpannableStringBuilder text=NoteFormat.decode(rich,body);for(int i=blocks.size()-1;i>=0;i--){Block b=blocks.get(i);if(b.id.equals(id))text.delete(b.start,b.end);}return new Mapped(text.toString(),rich==null||rich.isEmpty()?"":NoteFormat.encode(text));}
    static void reconcile(SQLiteDatabase db,long note,String oldBody,String body){Set<String> next=ids(body);for(String id:ids(oldBody))if(!next.contains(id))db.delete("note_docs","note_id=? AND doc_id=?",new String[]{""+note,id});for(String id:next){try(android.database.Cursor c=db.rawQuery("SELECT name,mime FROM docs WHERE id=?",new String[]{id})){if(!c.moveToFirst()||!isImage(c.getString(0),c.getString(1)))continue;}ContentValues link=new ContentValues();link.put("note_id",note);link.put("doc_id",id);db.insertWithOnConflict("note_docs",null,link,SQLiteDatabase.CONFLICT_IGNORE);}}
    private InlineImages(){}
}
